/// Returns `true` if and only if the difference between `a` and `b` lies strictly
/// within the open interval (-tol, tol). That is, |a - b| < tol.
///
/// # Panics
///
/// This function does not panic under normal use, given that `tol` is strictly
/// positive as per the problem statement. If you supply `tol <= 0`, the behavior
/// is still correct as an arithmetic comparison, but it will always return `false`.
fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Promote to i16 to avoid potential overflow when subtracting extremes.
    let diff = (a as i16) - (b as i16);
    diff.abs() < (tol as i16)
}

/// Given two equally‐sized vectors of i8 values and a strictly positive tolerance,
/// returns a Vec<bool> where each entry indicates whether the corresponding pair
/// of elements is “close” in the sense of `is_close_i8`.
///
/// # Panics
///
/// Panics if `a.len() != b.len()`. The problem statement guarantees non-zero
/// and equal lengths, and `tol` strictly positive.
fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    assert!(
        a.len() == b.len(),
        "Input vectors must have the same length"
    );

    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| is_close_i8(x, y, tol))
     .collect()
}

