        assert!(!is_close_i8(10, 16, 5)); // |10 - 16| = 6 >= 5
        assert!(!is_close_i8(-128, 127, 10)); // | -128 - 127 | = 255 >= 10
        assert!(is_close_i8(-5, 5, 11)); // | -5 - 5 | = 10 < 11
        assert!(!is_close_i8(0, 0, 0)); // tol == 0, |0-0|=0 < 0 is false
